(() => {
  const clean = (s) => ((s || '') + '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const 值 = (p) => [...document.querySelectorAll('input')].filter((x) => vis(x) && (x.placeholder || '').includes(p));
  const 公司 = 值('北京华品博睿'), 行业 = 值('所属行业'), 职位 = 值('职位名称'), 时间 = 值('在职时间');
  const 内容 = [...document.querySelectorAll('textarea')].filter(vis)[0];
  const 报错 = [...document.querySelectorAll('.form-error-tip')].filter(vis).map((x) => clean(x.innerText));
  const 问 = [];
  if (!公司.length || !clean(公司[0].value)) 问.push('公司=空');
  else if (clean(公司[0].value).indexOf('天鹅到家') < 0) 问.push('公司=' + clean(公司[0].value));
  if (!行业.length || !clean(行业[0].value)) 问.push('行业=空');
  if (!职位.length || !clean(职位[0].value)) 问.push('职位=空');
  if (时间.length < 2 || !clean(时间[0].value) || !clean(时间[1].value)) 问.push('时间=' + 时间.map((x) => clean(x.value)).join('~'));
  if (!内容 || 内容.value.length < 100) 问.push('正文=' + (内容 ? 内容.value.length : 0) + '字');
  if (报错.length) 问.push('页面报错=' + 报错.join('/'));
  if (问.length) return '不保存，缺：' + 问.join('；');
  const ok = document.querySelector('[ka=resume_form_work_ok]');
  if (!ok) return '全对但没找到完成按钮';
  ok.click();
  return '闸门全过，已点完成：' + clean(公司[0].value) + ' / ' + clean(行业[0].value) + ' / ' + clean(职位[0].value) + ' / ' + clean(时间[0].value) + '-' + clean(时间[1].value) + ' / 正文' + 内容.value.length + '字';
})()

